import React, { forwardRef, useEffect, useImperativeHandle } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { Button } from '../../../../../buttons/button/Button.js';
import { KeyboardShortcutTooltip } from '../../../../../content/keyboard-shortcut-tooltip/KeyboardShortcutTooltip.js';
import { Menu } from '../../../../../navigation/menu/Menu.js';
import { Tooltip } from '../../../../../overlays/tooltip/Tooltip.js';
import { useToolbarMenu } from '../hooks/useToolbarMenu.js';

/**
 * @internal
 */
export interface ChartToolbarControlProps {
  /* Icon to be added as a prefix */
  prefixIcon: JSX.Element;
  /* Text to be displayed when hovering the button */
  tooltipText?: string;
  /* Test id for testing purposes */
  testId?: string;
  /** Wether the button is selected or not */
  selected?: boolean;
  /* The function to call when the button is clicked */
  onClick: (event: MouseEvent) => void;
  /* The function to call when a key is pressed and released when selecting this control*/
  onKeyDown?: (event: KeyboardEvent) => void;
  /* The current tab index for the control */
  tabIndex?: number;
  /* Indicates wether the button is disabled, also will disable the key shortcut text */
  disabled?: boolean;
  /* Forces to close the tooltip */
  hideTooltip?: boolean;
  /* text to be displayer as key shortcut */
  tooltipKeyShortcut?: string;
}

const ACTIVE_STATE_UNDERLINE_WIDTH = 20;

const StyledButton = /* @__PURE__ */ styled(Button)<{
  selected: boolean;
  disable: boolean;
}>(({ selected, disable }) => ({
  position: 'relative',
  color: selected
    ? Colors.Icon.Primary.Default
    : disable
    ? Colors.Text.Neutral.Disabled
    : Colors.Text.Neutral.Default,
  '&:hover': {
    color: disable ? Colors.Text.Neutral.Disabled : Colors.Text.Neutral.Default,
    backgroundColor: disable
      ? 'transparent'
      : Colors.Background.Field.Neutral.DefaultHover,
  },
  '::after': {
    content: '""',
    position: 'absolute',
    bottom: '-2px',
    height: selected ? '2px' : 0,
    width: `${ACTIVE_STATE_UNDERLINE_WIDTH}px`,
    left: 0,
    right: 0,
    margin: 'auto',
    background: Colors.Border.Primary.Accent,
  },
}));

const StyledText = /* @__PURE__ */ styled('span')({
  textTransform: 'capitalize',
});

const StyledShortcut = /* @__PURE__ */ styled('span')({
  color: Colors.Text.Neutral.Subdued,
});

const StyledMenuItem = /* @__PURE__ */ styled(Menu.Item)<{ selected: boolean }>(
  ({ selected }) => ({
    backgroundColor: selected
      ? Colors.Background.Field.Neutral.DefaultActive
      : 'transparent',
  }),
);

const StyledMenuItemContent = styled('div')({
  display: 'flex',
  justifyContent: 'space-between',
  width: '100%',
});

/**
 * ChartToolbar generic control component
 * @internal
 */
export const Control = /* @__PURE__ */ forwardRef<
  HTMLButtonElement | undefined,
  ChartToolbarControlProps
>((props: ChartToolbarControlProps, forwardedRef) => {
  const {
    prefixIcon,
    tooltipText,
    testId,
    selected = false,
    onClick,
    onKeyDown,
    tabIndex,
    disabled = false,
    hideTooltip = false,
    tooltipKeyShortcut,
  } = props;
  const localRef = React.useRef<HTMLButtonElement>();
  const isMenuElement = useToolbarMenu();

  useEffect(() => {
    if (tabIndex === 0) {
      localRef.current?.focus();
    }
  }, [tabIndex]);

  useImperativeHandle(forwardedRef, () => localRef.current);

  const handleClick = (event: MouseEvent) => {
    if (!disabled) {
      onClick(event);
    }
  };

  const handleKeyDown = (event: KeyboardEvent) => {
    if (!disabled) {
      onKeyDown?.(event);
    }
  };

  const styledButton = (
    <StyledButton
      ref={localRef}
      variant="default"
      tabIndex={tabIndex}
      data-testid={testId}
      selected={selected}
      aria-label={tooltipText}
      onKeyDown={handleKeyDown}
      onMouseUp={handleClick}
      disable={disabled}
    >
      <Button.Prefix>{prefixIcon}</Button.Prefix>
    </StyledButton>
  );

  return isMenuElement ? (
    <StyledMenuItem
      selected={selected ? selected : false}
      onSelect={onClick}
      disabled={disabled}
    >
      <Menu.ItemIcon>{prefixIcon}</Menu.ItemIcon>
      <StyledMenuItemContent>
        <StyledText>{tooltipText}</StyledText>
        <StyledShortcut>&nbsp;{tooltipKeyShortcut}</StyledShortcut>
      </StyledMenuItemContent>
    </StyledMenuItem>
  ) : tooltipText ? (
    tooltipKeyShortcut ? (
      <KeyboardShortcutTooltip
        keys={tooltipKeyShortcut}
        text={tooltipText}
        disabled={hideTooltip}
        shortcutDisabled={disabled}
      >
        {styledButton}
      </KeyboardShortcutTooltip>
    ) : (
      <Tooltip text={tooltipText} disabled={hideTooltip}>
        {styledButton}
      </Tooltip>
    )
  ) : (
    styledButton
  );
});

Control['displayName'] = 'ChartToolbar.Control';
